<script setup>
defineProps({ runtime: Object, tools: { type: Array, default: () => [] }, runs: { type: Array, default: () => [] }, skills: { type: Array, default: () => [] }, connectors: Object, operations: Object, workItems: { type: Array, default: () => [] }, evaluations: Object, role: String, buttonPermissionIds: { type: Array, default: () => [] } });
defineEmits(['run-evaluations']);
</script>

<template>
  <div v-if="runtime" class="page private-agent-page">
    <section v-if="operations" class="agent-ops-grid"><article class="panel"><span class="eyebrow">ZHINAO OPS</span><h3>智脑运行健康度</h3><b class="ops-status">{{ operations.status }}</b><p>模型 P95 {{ operations.telemetry.latencyP95 }} · 错误率 {{ operations.telemetry.errorRate }}</p></article><article class="panel"><span class="eyebrow">CONTROLLED QUEUE</span><h3>受控任务队列</h3><div class="ops-metrics"><b>{{ operations.metrics.queueDepth }}</b><span>队列深度</span><b>{{ operations.metrics.draftWorkItems }}</b><span>草稿工作项</span></div></article><article class="panel"><span class="eyebrow">POLICY ALERT</span><h3>{{ operations.alerts[0].title }}</h3><p>{{ operations.alerts[0].detail }}</p></article></section>

    <section v-if="evaluations" class="panel agent-evaluation"><div class="section-header"><div><span class="eyebrow">CONTROL EVALUATION</span><h2>智脑控制评测</h2><p>{{ evaluations.policy }}</p></div><button class="outline-button" :disabled="!evaluations.canRun || !buttonPermissionIds.includes('agent.evaluation.run')" @click="$emit('run-evaluations')">运行评测</button></div><div class="evaluation-summary"><div><b>{{ evaluations.latest?.status || '尚未运行' }}</b><span>最近结果</span></div><div><b>{{ evaluations.latest?.passRate || '--' }}</b><span>通过率</span></div><div><b>{{ evaluations.latest?.executedAt ? new Date(evaluations.latest.executedAt).toLocaleString() : '--' }}</b><span>最近运行</span></div></div><div v-if="evaluations.latest?.results" class="evaluation-cases"><article v-for="item in evaluations.latest.results" :key="item.id"><b :class="item.status">{{ item.status }}</b><span>{{ item.name }}</span><small>{{ item.expectation }}</small></article></div><p v-else class="empty-run">当前角色可查看评测摘要；仅具备按钮权限的管理角色可执行包含权限、证据、确认和提示词防护的控制评测。</p></section>

    <div class="agent-hero"><div><span class="eyebrow">ZHINAO CONTROL PLANE</span><h2>{{ runtime.name }}</h2><p>智脑是企业唯一的智能入口，也是受权限管理的服务主体。它不拥有业务数据的永久权限；每次任务必须通过用户、设备、智脑身份、数据域和工作流策略的联合判定。</p></div><div class="agent-id"><span>ZHINAO PRINCIPAL</span><b>{{ runtime.agentId }}</b><em>{{ runtime.status }} · {{ runtime.authorization?.decision }}</em></div></div>

    <section class="agent-runtime-grid"><article class="panel"><span class="eyebrow">AUTHORIZATION SUBJECT</span><h3>智脑权限主体</h3><div class="runtime-kv"><span>主体类型</span><b>{{ runtime.authorization?.principal?.type }}</b></div><div class="runtime-kv"><span>凭据引用</span><b>{{ runtime.authorization?.principal?.credential }}</b></div><div class="runtime-kv"><span>默认策略</span><b class="safe">默认拒绝</b></div><div class="runtime-kv"><span>短时授权</span><b class="safe">用户与策略交集后发放</b></div></article><article class="panel"><span class="eyebrow">MODEL RUNTIME</span><h3>{{ runtime.runtime.provider }}</h3><div class="runtime-kv"><span>运行模式</span><b>{{ runtime.runtime.mode }}</b></div><div class="runtime-kv"><span>推理模型</span><b>{{ runtime.runtime.model }}</b></div><div class="runtime-kv"><span>端点</span><b>{{ runtime.runtime.baseUrl }}</b></div><div class="runtime-kv"><span>数据出域</span><b class="safe">{{ runtime.runtime.dataEgress }}</b></div></article><article class="panel"><span class="eyebrow">GUARDRAILS</span><h3>安全执行护栏</h3><div class="guardrail-list"><div v-for="(guard,index) in runtime.guardrails" :key="guard"><i>{{ String(index + 1).padStart(2,'0') }}</i><span>{{ guard }}</span></div></div></article></section>

    <section class="panel sub-agent-board"><div class="section-header"><div><span class="eyebrow">EFFECTIVE PERMISSIONS</span><h2>当前角色下的智脑授权范围</h2><p>{{ runtime.authorization?.note }}</p></div><b>{{ runtime.authorization?.allowedDomains?.length || 0 }} 个数据域</b></div><div class="sub-agent-grid"><article v-for="domain in runtime.authorization?.allowedDomains || []" :key="domain.id"><span>{{ domain.id }}</span><h3>{{ domain.name }}</h3><p>可访问对象：{{ domain.objects.join('、') }}</p><b>可发起流程：{{ domain.workflows.join('、') }}</b></article><p v-if="!runtime.authorization?.allowedDomains?.length" class="empty-run">当前角色未获得智脑领域授权。</p></div></section>

    <section class="panel sub-agent-board"><div class="section-header"><div><span class="eyebrow">BUSINESS LINE CONTROL</span><h2>业务条线权限</h2><p>{{ runtime.businessAccess?.policy }}</p></div><b>{{ runtime.businessAccess?.grants?.length || 0 }} 项能力</b></div><div class="sub-agent-grid"><article v-for="grant in runtime.businessAccess?.grants || []" :key="grant.id"><span>{{ grant.id }}</span><h3>{{ grant.name }}</h3><p>{{ grant.description }}</p><b>{{ grant.risk }} 风险动作</b></article><p v-if="!runtime.businessAccess?.grants?.length" class="empty-run">当前角色未配置可由智脑发起的业务条线能力。</p></div></section>

    <section class="panel sub-agent-board"><div class="section-header"><div><span class="eyebrow">SPECIALIST CAPABILITIES</span><h2>智脑可调度的专业能力</h2><p>专业能力不直接访问数据；它们必须使用本次任务由策略中心发放的受控上下文。</p></div></div><div class="sub-agent-grid"><article v-for="agent in runtime.subAgents" :key="agent.id"><span>{{ agent.id }}</span><h3>{{ agent.name }}</h3><p>{{ agent.scope }}</p><b>受智脑权限主体约束</b></article></div></section>

    <section class="panel skill-catalog"><div class="section-header"><div><span class="eyebrow">BUSINESS SKILL PACKS</span><h2>版本化业务技能包</h2><p>技能包定义意图、可调用工具和安全边界；模型可替换，业务控制逻辑保持可审计。</p></div><b>{{ skills.length }} 项技能</b></div><div class="skill-grid"><article v-for="skill in skills" :key="skill.id"><span>{{ skill.domain }} · v{{ skill.version }}</span><h3>{{ skill.name }}</h3><p>{{ skill.description }}</p><div><b>{{ skill.mode }}</b><em>{{ skill.risk }}风险</em></div><small>{{ skill.tools.join(' · ') }}</small><footer v-if="skill.evaluation"><b :class="skill.evaluation.status">评测 {{ skill.evaluation.status }}</b><span>{{ skill.evaluation.scenarios }} 场景 · {{ skill.evaluation.lastRun }}</span></footer></article></div></section>

    <section v-if="connectors" class="panel connector-catalog"><div class="section-header"><div><span class="eyebrow">MCP CONNECTOR CONTROL PLANE</span><h2>受控系统连接器</h2><p>{{ connectors.policy }}</p></div><b>{{ connectors.connectors.filter((item) => item.accessible).length }} / {{ connectors.connectors.length }} 可访问</b></div><div class="connector-grid"><article v-for="connector in connectors.connectors" :key="connector.id" :class="{ blocked: !connector.accessible }"><header><span>{{ connector.system }}</span><b>{{ connector.accessible ? '已授予' : '未授权' }}</b></header><h3>{{ connector.name }}</h3><p>{{ connector.transport }} · {{ connector.classification }}</p><div><span>对象</span><b>{{ connector.objects.join('、') }}</b></div><div><span>写入</span><b>{{ connector.writeMode }}</b></div><div><span>工具</span><code>{{ connector.visibleTools.join(' · ') || '策略拒绝' }}</code></div><div v-if="connector.leasePolicy"><span>密钥租约</span><b>{{ connector.leasePolicy.maxTtlSeconds }} 秒 · v{{ connector.leasePolicy.version }}</b></div><small>{{ connector.credentialRef }}</small></article></div></section>

    <section class="panel tool-catalog"><div class="section-header"><div><span class="eyebrow">TOOL REGISTRY</span><h2>受控工具目录</h2><p>智脑提出调用计划后，权限管理中心会再次验证本次短时授权；未经授权的工具和工作流会被拒绝。</p></div><b>{{ tools.length }} 项工具</b></div><div class="tool-table"><div class="tool-head"><span>工具</span><span>权限范围</span><span>风险</span><span>执行模式</span><span>说明</span></div><div v-for="tool in tools" :key="tool.id" class="tool-row"><strong>{{ tool.name }}<small>{{ tool.id }}</small></strong><code>{{ tool.scope }}</code><span :class="tool.risk === '高' ? 'risk-high' : tool.risk === '中' ? 'risk-medium' : 'risk-low'">{{ tool.risk }}</span><b>{{ tool.mode }}</b><p>{{ tool.description }}</p></div></div></section>

    <section class="panel agent-runs"><div class="section-header"><div><span class="eyebrow">EXECUTION RECORDS</span><h2>任务运行与完整证据链</h2><p>逐次记录受控检索、授权、安全检查、确认、工具调用、业务回执和哈希完整性。</p></div><b>{{ runs.length }} 条</b></div><div v-if="runs.length" class="run-list"><article v-for="run in runs" :key="run.id"><div class="run-heading"><strong>{{ run.id }}</strong><span>{{ run.skill?.name || run.domain }} · {{ run.status }}</span></div><p>{{ run.input }}</p><small>授权域：{{ run.authorization?.grantedDomains?.join('、') || '历史记录' }}</small><details v-if="run.evidence?.length"><summary>业务证据（{{ run.evidence.length }}）</summary><div class="run-evidence"><div v-for="item in run.evidence" :key="`${item.source}-${item.id}`"><b>{{ item.source }}</b><code>{{ item.id }}</code><span>{{ item.title }}</span><small>{{ item.classification }} · {{ item.version }} · #{{ item.contentHash?.slice(0, 12) }}</small></div></div></details><details v-if="run.plan?.length"><summary>执行计划（{{ run.plan.length }}）</summary><ol class="run-plan"><li v-for="item in run.plan" :key="`${run.id}-${item.tool}`"><code>{{ item.tool }}</code><b>{{ item.status }}</b><small>{{ item.owner }}</small></li></ol></details><details v-if="run.evidenceTrace" class="run-trace"><summary>证据追踪（{{ run.evidenceTrace.eventCount }} 个事件）</summary><div class="run-trace-integrity"><code>{{ run.evidenceTrace.id }}</code><b :class="{ valid: run.evidenceTrace.integrity?.valid }">{{ run.evidenceTrace.integrity?.valid ? 'SHA-256 哈希链有效' : '完整性异常' }}</b></div><ol><li v-for="event in run.evidenceTrace.events" :key="event.id"><i/><div><header><b>{{ event.summary }}</b><time>{{ new Date(event.createdAt).toLocaleString() }}</time></header><small>{{ event.stage }} · {{ event.type }} · {{ event.status }}</small><details v-if="event.details && Object.keys(event.details).length" class="run-event-payload"><summary>事件字段</summary><pre>{{ JSON.stringify(event.details, null, 2) }}</pre></details><code>#{{ event.hash.slice(0, 16) }} / prev {{ event.previousHash?.slice(0, 10) || 'ROOT' }}</code></div></li></ol></details><footer v-if="run.execution"><span>执行结果</span><b>{{ run.execution.status }}</b><code>{{ run.execution.businessRecordId || run.execution.requisitionId || '--' }}</code></footer></article></div><p v-else class="empty-run">尚无运行记录。请从任一智脑端发起业务请求。</p></section>
  </div><div v-else class="loading">正在加载智脑运行时…</div>
</template>
